/**
 *
 * AutoCompleteArrow is a component that displays the arrow of an autocomplete popup.
 *
 * [Live Demo](https://www.primereact.org/autocomplete/)
 *
 * @module AutoCompleteArrow
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { AutoCompleteRootInstance } from './AutoCompleteRoot.types';
/**
 * Defines passthrough(pt) options type in AutoCompleteArrow component.
 */
export type AutoCompleteArrowPassThroughType<E> = PassThroughType<AutoCompleteArrowInstance, E>;
/**
 * Defines passthrough(pt) options of AutoCompleteArrow component.
 */
export interface AutoCompleteArrowPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: AutoCompleteArrowPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in AutoCompleteArrow component.
 */
export interface AutoCompleteArrowProps extends BaseComponentProps<AutoCompleteArrowInstance, unknown, AutoCompleteArrowPassThrough> {
}
/**
 * Defines valid state in AutoCompleteArrow component.
 */
export interface AutoCompleteArrowState {
}
/**
 * Defines the methods and properties exposed by AutoCompleteArrow component.
 */
export interface AutoCompleteArrowExposes {
    /**
     * The AutoComplete component instance.
     */
    autocomplete: AutoCompleteRootInstance | undefined | null;
}
/**
 * Instance of AutoCompleteArrow component.
 */
export type AutoCompleteArrowInstance = ComponentInstance<AutoCompleteArrowProps, AutoCompleteArrowState, AutoCompleteArrowExposes>;
